public func valueOrErrno<I: FixedWidthInteger>(
    retryOnInterrupt: Bool = true,
    _ fn: () -> I
) -> Result<I, Errno> {
    while true {
        Errno.clear()
        let result = fn()
        if result == -1 {
            let errno = Errno._current
            if errno == .interrupted, retryOnInterrupt {
                continue
            } else {
                return .failure(errno)
            }
        } else {
            return .success(result)
        }
    }
}
```

