/// This safely destroys an UnsafeMutableBufferPointer by deinitializing and deallocating the underlying memory. This ensures that if the pointer contains non-trivial Swift types that no accidental memory leaks will occur, as can happen if UnsafeMutableBufferPointer.deallocate() is used.
fileprivate func deinitializeAndDeallocate() {
    guard let basePointer = self.baseAddress else {
        // If there's no base address, who cares?
        return
    }

    // This is the safe way to do things: the moment that deinitialize
    // is called, we deallocate.
    let rawPointer = basePointer.deinitialize(count: self.count)
    rawPointer.deallocate()
}
