        assert(destCompleteStorage.count >= index + allBytesCount)
        let dest = destCompleteStorage[index..<index + allBytesCount]
        dispatchData.copyBytes(to: .init(rebasing: dest), count: dest.count)
    }
    return allBytesCount
}
