internal mutating func closeIfNecessary() {
    switch self.state {
    case .idle:
        // We don't own the handle so don't close it.
        self.state = .done

    case .open(_, let mode, _), .openPausedProducing(_, let mode, _):
        self.state = .done
        switch mode {
        case .readdir(let dir):
            _ = Libc.closedir(dir)
        case .fts(let fts):
            _ = Libc.ftsClose(fts)
        }

    case .done:
        ()

    case .modifying:
        fatalError()
    }
}
