@_spi(Testing)
public func optionalValueOrErrno<R>(
    retryOnInterrupt: Bool = true,
    _ fn: () -> R?
) -> Result<R?, Errno> {
    while true {
        Errno.clear()
        if let result = fn() {
            return .success(result)
        } else {
            let errno = Errno._current
            if errno == .interrupted, retryOnInterrupt {
                continue
            } else if errno.rawValue == 0 {
                return .success(nil)
            } else {
                return .failure(errno)
            }
        }
    }
}
