package func withLock<Result>(
    _ body: () -> (workDelta: Int, signal: Signal, result: Result)
) -> Result {
    self._storage.lock.lock()
    let (workDelta, signal, result) = body()
    self._storage.workAvailable += workDelta
    self._storage.lock.unlock()
    self._signal(signal)
    return result
}
