    if decodeMode == .last && (self._buffer == nil || self._buffer!.readableBytes == 0) {
        var emptyBuffer = self._buffer ?? ByteBuffer()
        let message = try self._decoder.decodeLast(buffer: &emptyBuffer, seenEOF: seenEOF)
