public func valueOrErrno<R>(
    retryOnInterrupt: Bool = true,
    _ fn: () -> R
) -> Result<R, Errno> {
    while true {
        Errno.clear()
        let value = fn()
        let errno = Errno._current
        if errno.rawValue == 0 {
            return .success(value)
        } else if errno == .interrupted, retryOnInterrupt {
            continue
        } else {
            return .failure(errno)
        }
    }
}
